changeSet.sql:
ALTER TABLE public.personal_goal DROP CONSTRAINT ck_personal_goal_content;
ALTER TABLE public.personal_goal ADD CONSTRAINT ck_personal_goal_content
    CHECK (words IS NULL OR goal_id IS NOT NULL);

rollback.sql:
ALTER TABLE public.personal_goal DROP CONSTRAINT ck_personal_goal_content;
ALTER TABLE public.personal_goal ADD CONSTRAINT ck_personal_goal_content
    CHECK ((goal_id IS NULL) = (words IS NULL));
